 				if (firstLineBreak[0] === -1) {
 					break;
 				}
 				start += firstLineBreak[1];
 			}
 			renderStatementList(this.body, code, start, this.end, options);
 		} else {
 			super.render(code, options);
 		}
 	}

 	protected applyDeoptimizations() {}
