interface LocateOptions {
	offsetColumn?: number;
	offsetLine?: number;
	startIndex?: number;
}

export interface Location {
	character: number;
	column: number;
	line: number;
}

export function locate(source: string, search: string | number, options?: LocateOptions): Location {
	const character =
		typeof search === 'string' ? source.indexOf(search, options?.startIndex) : search;
	if (character < 0 || character > source.length) {
		throw new Error(`Could not locate ${JSON.stringify(search)} in source.`);
	}

	let line = options?.offsetLine ?? 0;
	for (let index = 0; index < character; index++) {
		if (source.charCodeAt(index) === 10) line++;
	}

	const lineStart = character > 0 ? source.lastIndexOf('\n', character - 1) + 1 : 0;
	return {
		character,
		column: character - lineStart + (options?.offsetColumn ?? 0),
		line
	};
}
