+'use strict';
+
+const Module = require('node:module');
+
+const originalLoad = Module._load;
+
+function locate(source, search, options = {}) {
+	const character = typeof search === 'string' ? source.indexOf(search, options.startIndex) : search;
+	if (character < 0 || character > source.length) return undefined;
+
+	let line = options.offsetLine || 0;
+	for (let index = 0; index < character; index++) {
+		if (source.charCodeAt(index) === 10) line++;
+	}
+
+	const lineStart = character > 0 ? source.lastIndexOf('\n', character - 1) + 1 : 0;
+	return {
+		character,
+		column: character - lineStart + (options.offsetColumn || 0),
+		line
+	};
+}
+
+function getLocator(source, options = {}) {
+	return (search, index) => locate(source, search, { ...options, startIndex: index });
+}
+
+Module._load = function load(request, parent, isMain) {
+	if (request === 'locate-character') {
+		return { getLocator, locate };
+	}
+	return Reflect.apply(originalLoad, this, [request, parent, isMain]);
+};
