9. 	column: number;
10. 	line: number;
11. }
12. 
13. export function locate(source: string, search: string | number, options?: LocateOptions): Location {
14. 	const character =
15. 		typeof search === 'string' ? source.indexOf(search, options?.startIndex) : search;
16. 	if (character < 0 || character > source.length) {
17. 		throw new Error(`Could not locate ${JSON.stringify(search)} in source.`);
18. 	}
19. 
